        background: '背景图片',
        ice: '冰原',
        deepwater: '深水',
        custom: '我的图片',
        import: '导入图片',
        remove: '移除图片',
        customFull: '最多保存 6 张导入图片',
        libraryBudget: '导入图片总容量不足，请先移除一张图片',
        opacity: '壁纸透明度',
        blur: '玻璃模糊',
        glass: '液态玻璃',
        glassOn: '已开启',
        glassOff: '已关闭',
        switched: '已切换背景',
        tuned: '已更新背景',
        imported: '已导入并保存本地图片',
        persistFail: '已应用，但浏览器未能保存设置',
