        ice: 'Ice',
        deepwater: 'Deepwater',
        custom: 'My image',
        import: 'Import image',
        remove: 'Remove',
        customFull: 'You can keep up to 6 imported images',
        libraryBudget: 'Not enough space for imported images; remove one first',
        opacity: 'Wallpaper opacity',
        blur: 'Glass blur',
        glass: 'Liquid Glass',
        glassOn: 'On',
