      var raw = storageGet(CUSTOM_LIBRARY_STORAGE)
      if (raw) {
        try {
          var parsed = JSON.parse(raw)
          if (Array.isArray(parsed)) {
            return parsed.filter(function (item) {
              return item
                && typeof item.id === 'string'
                && typeof item.data === 'string'
                && item.data.indexOf('data:image/') === 0
            })
          }
        } catch (_error) {}
      }
