          var tertiary = surface === 'dark' ? 'rgba(226, 234, 255, 0.60)' : '#687282'
          var caption = surface === 'dark' ? 'rgba(226, 234, 255, 0.48)' : '#7b8492'
          var dimmed = surface === 'dark' ? 'rgba(226, 234, 255, 0.34)' : '#9aa2ae'
